import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BGk6IKDC.js";const h=JSON.parse('{"title":"Catalog text lives in translation files","description":"","frontmatter":{"status":"accepted","date":"2026-10-26T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0015-catalog-text-lives-in-translation-files.md","filePath":"docs/adr/0015-catalog-text-lives-in-translation-files.md"}'),n={name:"docs/adr/0015-catalog-text-lives-in-translation-files.md"};function i(l,e,r,c,d,g){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="catalog-text-lives-in-translation-files" tabindex="-1">Catalog text lives in translation files <a class="header-anchor" href="#catalog-text-lives-in-translation-files" aria-label="Permalink to &quot;Catalog text lives in translation files&quot;">​</a></h1><p>Amends <a href="./0008-curated-catalog-with-stable-slugs">ADR 0008</a>.</p><p>Exercise names, instructions, variation notes and aliases move out of <code>catalog/data/exercises.json</code> into the <code>catalog</code> namespace of the translation files (ADR 0014), keyed by slug: <code>goblet-squat.name</code>, <code>goblet-squat.instructions.0</code>, <code>goblet-squat.variationNote</code>, <code>goblet-squat.aliases</code>. Aliases are one comma-separated message per language, since a message is a single string; they are never shown. <code>exercises.json</code> keeps the structure: slug, movement pattern, muscles, equipment, measurement, variations, <code>retired</code> and <code>version</code>.</p><p>The text moves so translators can edit it in Fink alongside the rest of the app. What the phone receives does not change shape: the build merges the text back into the bundled catalog, so each catalog version stays one self-contained document, copied into the database and later published by the server as ADR 0008 says, with each text as a map from language to string (<code>{&quot;en&quot;: &quot;Goblet squat&quot;, &quot;fr&quot;: &quot;Squat gobelet&quot;}</code>). That is the JSON phones already store, so existing catalog entries decode unchanged and no migration is needed.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Changing an exercise&#39;s text raises the catalog <code>version</code>, as any catalog change does. Fink&#39;s pull requests don&#39;t, so CI fails when catalog text changes and <code>version</code> doesn&#39;t, and the version is raised before merging.</li><li>A slug is also a message id prefix, one more reason it never changes.</li><li>Reordering an exercise&#39;s instructions renumbers their ids, and translators see the change as new messages.</li><li>The build fails when an exercise has no name in a shipped language, or a message names a slug the catalog lacks.</li></ul>',6)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
